import { mkdirSync, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const OUT_DIR = 'D:/_work/Artisyn-LogHub/_repo/docs/product-kb/opencode/samples';
const SESSION_ID = 'ses_e2b50f18bffehLMmcoYB1TDKE5';

const db = new DatabaseSync(
  path.join(os.homedir(), '.local', 'share', 'opencode', 'opencode.db'),
  { readOnly: true },
);

const session = db.prepare('select * from session_v2 where id=?').get(SESSION_ID);
if (!session) throw new Error('session not found: ' + SESSION_ID);
const messages = db
  .prepare('select * from session_message where session_id=? order by seq asc')
  .all(SESSION_ID)
  .map((m) => ({ ...m, data: JSON.parse(m.data) }));

mkdirSync(OUT_DIR, { recursive: true });

const exportedAt = new Date().toISOString();
const base = `${SESSION_ID}`;

// --- raw JSON ---------------------------------------------------------------
const raw = {
  exportedAt,
  source: path.join(os.homedir(), '.local', 'share', 'opencode', 'opencode.db'),
  session: { ...session, metadata: session.metadata ? JSON.parse(session.metadata) : null },
  messages,
};
writeFileSync(path.join(OUT_DIR, `${base}.json`), JSON.stringify(raw, null, 2), 'utf8');

// --- readable markdown ------------------------------------------------------
const iso = (ms) => (ms ? new Date(ms).toISOString() : '');
const fence = (lang, text) => {
  const body = String(text ?? '');
  const longest = Math.max(3, ...(body.match(/`+/g) ?? []).map((m) => m.length + 1));
  const f = '`'.repeat(longest);
  return `${f}${lang}\n${body}\n${f}`;
};
const truncate = (text, n = 1500) => {
  const s = String(text ?? '');
  return s.length > n ? `${s.slice(0, n)}\n… [truncated in markdown, full text in .json]` : s;
};

const out = [];
out.push(`# OpenCode session sample — ${session.title ?? session.slug}`);
out.push('');
out.push(`- Session: \`${session.id}\``);
out.push(`- Slug: \`${session.slug}\``);
out.push(`- Directory: \`${session.directory}\``);
out.push(`- Agent: \`${session.agent ?? ''}\`, model: \`${session.model ?? ''}\``);
out.push(`- Created: ${iso(session.time_created)}`);
out.push(`- Updated: ${iso(session.time_updated)}`);
out.push(`- Tokens: input ${session.tokens_input}, output ${session.tokens_output}, reasoning ${session.tokens_reasoning}, cache read ${session.tokens_cache_read}`);
out.push(`- Cost: ${session.cost}`);
out.push(`- Exported: ${exportedAt}`);
out.push('');

for (const m of messages) {
  const d = m.data;
  const when = iso(d.time?.created ?? m.time_created);

  if (m.type === 'user') {
    out.push(`## User — ${when}`);
    out.push('');
    out.push(d.text ?? '');
    if (d.files?.length) out.push('', `Files: ${d.files.map((f) => `\`${f}\``).join(', ')}`);
    out.push('');
    continue;
  }

  if (m.type === 'idle') {
    out.push(`## Idle — ${when} (${d.outcome ?? 'unknown'})`);
    out.push('');
    continue;
  }

  if (m.type === 'assistant') {
    const model = d.model ? `${d.model.providerID}/${d.model.id}${d.model.variant ? ` (${d.model.variant})` : ''}` : 'unknown';
    out.push(`## Assistant — ${when} — \`${model}\``);
    out.push('');
    for (const c of d.content ?? []) {
      if (c.type === 'reasoning' && c.text?.trim()) {
        out.push('<details><summary>Reasoning</summary>', '', truncate(c.text, 4000), '', '</details>', '');
      } else if (c.type === 'text' && c.text?.trim()) {
        out.push(c.text, '');
      } else if (c.type === 'tool') {
        const st = c.state ?? {};
        out.push(`### Tool: \`${c.name}\` — ${st.status ?? 'unknown'}`);
        out.push('');
        if (st.input !== undefined) out.push(fence('json', JSON.stringify(st.input, null, 2)), '');
        const content = st.content ?? [];
        const textParts = content.filter((x) => x.type === 'text').map((x) => x.text);
        if (textParts.length) out.push(fence('text', truncate(textParts.join('\n\n'))), '');
        if (st.status === 'error' && st.error) out.push(fence('json', JSON.stringify(st.error, null, 2)), '');
      }
    }
    continue;
  }

  out.push(`## ${m.type} — ${when}`);
  out.push('');
  out.push(fence('json', JSON.stringify(d, null, 2)));
  out.push('');
}

writeFileSync(path.join(OUT_DIR, `${base}.md`), out.join('\n'), 'utf8');

console.log('written:');
console.log(path.join(OUT_DIR, `${base}.json`));
console.log(path.join(OUT_DIR, `${base}.md`));
console.log('messages:', messages.length);
